metadata.vithanco:vgl:
vgraph goldrattEC: EC "Goldratt's EC" {
    node obj: CommonObjective "Reduce cost per Unit";
    node needSetup: Need "Reduce setup cost per unit";
    node needCarry: Need "Reduce carrying cost per unit";
    node wantLarge: Want "Run large batches";
    node wantSmall: Want "Run small batches";
    node conf: Conflict;
    node assFixed: Assumption "Setup cost is fixed and can't be reduced";
    node assBottleneck: Assumption "The machine being set up is a bottleneck with no spare capacity";
    edge obj -> needSetup: objective_to_need;
    edge obj -> needCarry: objective_to_need;
    edge needSetup -> wantLarge: need_to_want;
    edge needCarry -> wantSmall: need_to_want;
    edge wantLarge -> conf: want_to_conflict;
    edge wantSmall -> conf: want_to_conflict;
    edge needSetup -> assFixed: need_to_assumption;
    edge needSetup -> assBottleneck: need_to_assumption;
}
